export const LOOP_INFO: { id: string; name: string; text: string }[] = [{"id": "R1", "name": "Normalization", "text": "More people gambling makes gambling feel normal. That raises exposure, which brings more people in."}, {"id": "R2", "name": "Marketing", "text": "More spending, much of it by people already at risk, means more operator revenue. That pays for more marketing, which draws more people in."}, {"id": "R3", "name": "Chasing losses", "text": "Gambling harder brings bigger losses and financial stress. Gambling to cope makes people gamble harder still."}, {"id": "R4", "name": "Distress and isolation", "text": "Harm causes distress, family conflict and isolation. Isolated people gamble to cope, which deepens the harm."}, {"id": "B1", "name": "Harm visibility", "text": "More people at risk means more visible harm. Awareness builds pressure to reform: regulation gets stronger and cuts access, social acceptance falls, and fewer people enter risk."}, {"id": "B2", "name": "Help and treatment", "text": "More harm raises awareness, and spending by people at risk raises tax revenue and government spending on services. Help-seeking and treatment capacity grow, so more people exit risk and treatment reduces harm."}];
